import { expect, test } from "@playwright/test";
const assets=["/models/drums/drum-kit-shell-set.glb","/models/drums/hands/left-hold.glb","/models/drums/hands/right-hold.glb"];
async function ready(p:any){await expect(p.locator(".drum-kit-canvas")).toHaveAttribute("data-engine-status","ready");await expect.poll(()=>p.evaluate((u:string[])=>performance.getEntriesByType("resource").filter((x:any)=>u.some(v=>x.name.includes(v))).length,assets)).toBe(3);await p.waitForTimeout(250)}
async function data(p:any){return p.locator(".drum-kit-canvas").evaluate((h:any)=>{const c=h.querySelector("canvas"),r=h.getBoundingClientRect(),q=c.getBoundingClientRect();return {host:[r.width,r.height],canvas:[c.width,c.height,q.width,q.height],model:h.dataset.modelVersion,view:h.dataset.view,calls:+h.dataset.drawCalls,triangles:+h.dataset.triangles,static:+h.dataset.staticObjectCount}})}
test("v28 runtime",async({page,browser})=>{const errs:string[]=[];page.on("console",m=>{if(["error","warning"].includes(m.type())&&!m.text().includes("GL Driver Message"))errs.push(m.text())});await page.setViewportSize({width:807,height:361});await page.goto("/kit");await ready(page);console.log("KIT",JSON.stringify(await data(page)));const k=page.locator("canvas");await k.screenshot({path:"output/playwright/drum-model-qa-licensed-v2-final/runtime/kit-loaded.png"});await k.focus();for(const x of ["Space","f","j","k","l"])await page.keyboard.press(x);for(const pt of [{x:243,y:255},{x:184,y:224},{x:138,y:126},{x:250,y:175},{x:365,y:91}])await k.click({position:pt,force:true});expect(errs).toEqual([]);await page.setViewportSize({width:844,height:340});await page.goto("/practice");await ready(page);console.log("PRACTICE",JSON.stringify(await data(page)));const c=page.locator("canvas");await c.screenshot({path:"output/playwright/drum-model-qa-licensed-v2-final/runtime/practice-idle.png"});await page.getByRole("button",{name:"Start 4-count"}).click();await expect(page.locator(".mode-pill")).toHaveText("count-in");await page.evaluate(()=>window.advanceTime?.(4200));await expect(page.locator(".mode-pill")).toHaveText("playing");await page.keyboard.press("f");await page.waitForTimeout(65);await c.screenshot({path:"output/playwright/drum-model-qa-licensed-v2-final/runtime/practice-snare-hit.png"});await page.waitForTimeout(500);await c.screenshot({path:"output/playwright/drum-model-qa-licensed-v2-final/runtime/practice-rebound.png"});await page.goto("/trainer");await ready(page);console.log("TRAINER",JSON.stringify(await data(page)));await page.locator("canvas").screenshot({path:"output/playwright/drum-model-qa-licensed-v2-final/runtime/trainer-idle.png"});expect(await page.locator("canvas").count()).toBe(1);const ctx=await browser.newContext();const f=await ctx.newPage();let fallback=false;f.on("console",m=>{if(m.text().includes("licensed model load failed; keeping procedural fallback"))fallback=true});await f.route("**/models/drums/**/*.glb",r=>r.abort("failed"));await f.goto("/kit");await expect(f.locator(".drum-kit-canvas")).toHaveAttribute("data-engine-status","ready");await expect.poll(()=>fallback).toBe(true);await ctx.close()});
